# Простой пример рефлексивного агента
class SimpleReflexAgent:
    def __init__(self):
        self.rules = {
            'hot': 'turn_on_ac',
            'cold': 'turn_on_heater',
            'comfortable': 'do_nothing'
        }

    def perceive(self, environment):
        """Воспринимает текущее состояние"""
        return environment.get_temperature_status()

    def decide(self, percept):
        """Принимает решение на основе правил"""
        return self.rules.get(percept, 'do_nothing')

    def act(self, action, environment):
        """Выполняет действие"""
        environment.execute(action)

# Использование
agent = SimpleReflexAgent()
while True:
    percept = agent.perceive(environment)
    action = agent.decide(percept)
    agent.act(action, environment)

// Современный LLM-based агент (концептуально)
class LLMAgent {
  constructor(
    private llm: LanguageModel,
    private tools: Tool[],
    private memory: VectorStore
  ) {}

  async run(task: string): Promise<string> {
    // 1. Формируем план
    const plan = await this.createPlan(task);

    // 2. Выполняем шаги плана
    for (const step of plan.steps) {
      // Рассуждаем о следующем действии
      const thought = await this.think(step);

      // Выбираем и используем инструмент
      const tool = this.selectTool(thought);
      const result = await tool.execute(thought.params);

      // Сохраняем в память
      await this.memory.store({
        step,
        thought,
        action: tool.name,
        result
      });

      // Саморефлексия - нужна ли корректировка плана?
      const shouldAdjust = await this.reflect(result);
      if (shouldAdjust) {
        plan = await this.adjustPlan(plan, result);
      }
    }

    // 3. Формируем финальный ответ
    return this.synthesizeResponse();
  }
}
